//! The engine side: loading images, mapping tasks to instances, suspending the guest while a call is
//! pending, the return-to-guest path, fork and preemption.
//!
//! Drives any `Syscalls` implementation and never reaches into kernel internals. The import shims
//! in `src/generated.rs` are generated by `wasixv2-codegen`.

pub mod abi;
mod generated;
mod memory;
mod process;
mod signal;
mod thread;
mod wasixv2;

use std::sync::Arc;

pub use abi::{Abi, AbiInstance, Abis, EntryReturn, Role, VforkResume};
pub use generated::IMPORT_MODULE;
pub use memory::GuestMemory;
pub use process::VFORK_RETURN;
pub use thread::THREAD_ENTRY;
pub use wasixv2::Wasixv2;
use wasixv2_host::Host;
use wasixv2_syscalls::{Control, Errno, GuestAction, SysErr, SysResult, Syscalls, TaskId};
use wasmer::{
    AsyncFunctionEnvMut, FunctionEnv, Imports, Instance, Memory, MemoryError, Module, RuntimeError,
    Store,
};

#[derive(Debug, thiserror::Error)]
pub enum ExecError {
    #[error("instantiation failed: {0}")]
    Instantiate(#[from] wasmer::InstantiationError),
    #[error("missing export: {0}")]
    Export(#[from] wasmer::ExportError),
    #[error("cannot create the imported memory: {0}")]
    Memory(#[from] MemoryError),
    #[error("guest trapped: {0}")]
    Trap(RuntimeError),
    // TODO: once signals exist, kill the process with SIGSEGV instead, as
    // Linux does when the entry point returns, and drop this variant.
    #[error("`_start` returned without calling `exit_group`")]
    ReturnedFromStart,
    #[error("no registered ABI serves this module")]
    NoAbi,
}

/// Host state behind every import of one instance.
pub struct ExecEnv<S> {
    syscalls: Arc<S>,
    task: TaskId,
    memory: Option<Memory>,
    /// The instance's half of its ABI; set once the instance exists.
    abi: Option<Arc<dyn AbiInstance<S>>>,
    // ---- proc ----
    proc: process::ProcExports,
}

impl<S> ExecEnv<S> {
    fn new(syscalls: Arc<S>, task: TaskId, spawner: Arc<dyn process::Spawn>) -> Self {
        Self {
            syscalls,
            task,
            memory: None,
            abi: None,
            proc: process::ProcExports::new(spawner),
        }
    }

    pub fn syscalls(&self) -> &Arc<S> {
        &self.syscalls
    }

    /// The task the instance runs as; it changes when vfork switches the instance.
    pub fn task(&self) -> TaskId {
        self.task
    }

    /// The instance's half of its ABI, for the ABI's import shims.
    pub fn abi(&self) -> Option<&Arc<dyn AbiInstance<S>>> {
        self.abi.as_ref()
    }
}

/// The syscalls object and the current task of the instance behind `env`, which every import
/// reads on entry.
pub async fn caller_parts<S: 'static>(env: &AsyncFunctionEnvMut<ExecEnv<S>>) -> (Arc<S>, TaskId) {
    let env = env.read().await;
    (env.data().syscalls.clone(), env.data().task)
}

/// Raised from an import to unwind the guest after its thread group exited.
#[derive(Debug, thiserror::Error)]
#[error("thread group exited with status {0}")]
struct Exited(i32);

/// Runs `module`, a `wasixv2` program, as `task` until its thread group exits, and returns the
/// exit status. Threads the guest creates run where `host`'s executor starts them, and so do the
/// images of vfork children; images that `execve` loads replace `module`.
pub async fn run<S>(
    store: Store,
    module: &Module,
    syscalls: Arc<S>,
    task: TaskId,
    host: Arc<dyn Host>,
) -> Result<i32, ExecError>
where
    S: Syscalls + Control + Send + Sync + 'static,
{
    run_with_abis(
        store,
        module,
        syscalls,
        task,
        host,
        Arc::new(Abis::wasixv2()),
    )
    .await
}

/// [`run`] for a program of any ABI in `abis`, which also serves the images it loads.
pub async fn run_with_abis<S>(
    store: Store,
    module: &Module,
    syscalls: Arc<S>,
    task: TaskId,
    host: Arc<dyn Host>,
    abis: Arc<Abis<S>>,
) -> Result<i32, ExecError>
where
    S: Syscalls + Control + Send + Sync + 'static,
{
    process::run(store, module, syscalls, task, host, abis).await
}

/// Runs one image of `task`'s process until it exits or `execve` replaces it.
async fn run_image<S>(
    mut store: Store,
    module: &Module,
    syscalls: Arc<S>,
    task: TaskId,
    host: Arc<dyn Host>,
    abis: Arc<Abis<S>>,
) -> Result<process::Ended, ExecError>
where
    S: Syscalls + Control + Send + Sync + 'static,
{
    let abi = abis.require(module)?;
    let spawner = process::spawner(
        store.engine().clone(),
        syscalls.clone(),
        host.clone(),
        abis.clone(),
    );
    let env = FunctionEnv::new(&mut store, ExecEnv::new(syscalls.clone(), task, spawner));
    let mut imports = abi.imports(&mut store, &env);
    let imported = import_memory(&mut store, module, &mut imports)?;
    let instance = Instance::new(&mut store, module, &imports)?;
    let memory = match imported {
        Some(memory) => memory,
        None => instance.exports.get_memory("memory")?.clone(),
    };
    let bound = abi.bind(&instance, &mut store, task, Role::Process)?;
    // ---- thr ----
    let _threads = memory.as_shared(&store).map(|shared| {
        let image = thread::Image::new(&store, module, shared, syscalls.clone(), host, abi, abis);
        thread::register(&image, task)
    });
    env.as_mut(&mut store).memory = Some(memory);
    env.as_mut(&mut store).abi = Some(bound.clone());

    let store = store.into_async();
    match bound.start(&store).await {
        Ok(()) => match bound.on_entry_return() {
            EntryReturn::Exit(status) => Ok(process::Ended::Exited(
                process::exit_group(&*syscalls, task, status).await,
            )),
            EntryReturn::Fault => Err(ExecError::ReturnedFromStart),
        },
        Err(err) => match err.downcast::<Exited>() {
            Ok(Exited(status)) => Ok(process::Ended::Exited(status)),
            Err(err) => match err.downcast::<process::ExecNew>() {
                Ok(process::ExecNew(image)) => Ok(process::Ended::Exec(image)),
                Err(err) => Err(ExecError::Trap(err)),
            },
        },
    }
}

/// Creates the memory `module` imports, if any, with the limits and sharing its import declares.
/// libc-built guests import a shared memory so threads can share it; others export `memory`.
fn import_memory(
    store: &mut Store,
    module: &Module,
    imports: &mut Imports,
) -> Result<Option<Memory>, MemoryError> {
    let Some(import) = module.imports().memories().next() else {
        return Ok(None);
    };
    let memory = Memory::new(store, *import.ty())?;
    imports.define(import.module(), import.name(), memory.clone());
    Ok(Some(memory))
}

/// How a syscall made through an import ends, once the return-to-guest path ran.
#[derive(Debug)]
pub enum Outcome<T> {
    /// A signal interrupted the call and Linux would restart it: make the call again.
    Rerun,
    /// The call returns this to the guest. Restarts are resolved: an interrupted call that
    /// must not restart is `EINTR` here.
    Return(Result<T, Errno>),
    /// The instance now runs as another task ([`ExecEnv::task`]), and the call returns this
    /// value to it: 0 to a vfork child, or to a vfork parent its ABI resumes by returning
    /// ([`VforkResume::ReturnSuccess`]).
    Switched(i32),
    /// The import must raise this error: the thread group exited, `execve` replaced the image,
    /// or the guest unwound (`siglongjmp`, the vfork return).
    Unwind(RuntimeError),
}

/// The return-to-guest path: runs the work the kernel left for `task` (exit, thread start,
/// task switches, new images, signal handlers), then decides how the syscall that returned
/// `ret` ends. Every import, of any ABI, calls this after each syscall.
pub async fn complete<S: Syscalls + Control + 'static, T>(
    env: &AsyncFunctionEnvMut<ExecEnv<S>>,
    syscalls: &S,
    task: TaskId,
    ret: SysResult<T>,
) -> Outcome<T> {
    let mut ret = ret;
    let mut task = task;
    // The value a task switch made the call return, which replaces `ret`.
    let mut switched: Option<i32> = None;
    // `SA_RESTART` of the first handler run, which is the one that interrupted the call.
    let mut handled: Option<bool> = None;
    while let Some(action) = syscalls.take_pending(task) {
        match action {
            GuestAction::Exit(status) => {
                return Outcome::Unwind(RuntimeError::user(Box::new(Exited(status))));
            }
            GuestAction::StartThread {
                task: child,
                start_arg,
            } => {
                if !thread::start(syscalls, task, child, start_arg) {
                    ret = Err(SysErr::Errno(Errno::EAGAIN));
                }
            }
            // ---- proc ----
            GuestAction::SwitchTask {
                task: to,
                ret: value,
            } => {
                process::switch(env, to).await;
                task = to;
                switched = Some(value);
            }
            GuestAction::Exec { vfork_parent } => {
                let image = syscalls.take_image(task).unwrap_or_default();
                let Some(parent) = vfork_parent else {
                    return Outcome::Unwind(RuntimeError::user(Box::new(process::ExecNew(image))));
                };
                process::spawn_image(env, task, image).await;
                match vfork_resume(env, parent, task).await {
                    VforkResume::Unwind(err) => return Outcome::Unwind(err),
                    VforkResume::ReturnSuccess => (task, switched) = (parent, Some(0)),
                }
            }
            GuestAction::VforkReturn { parent, child } => {
                match vfork_resume(env, parent, child).await {
                    VforkResume::Unwind(err) => return Outcome::Unwind(err),
                    VforkResume::ReturnSuccess => (task, switched) = (parent, Some(0)),
                }
            }
            GuestAction::Signal(frame) => {
                handled.get_or_insert(frame.restarts());
                let Some(abi) = instance_abi(env).await else {
                    syscalls.signal_return(task, None);
                    return Outcome::Unwind(RuntimeError::new("signal delivery before bind"));
                };
                match abi.deliver_signal(env, &frame).await {
                    Ok(mask) => syscalls.signal_return(task, mask),
                    Err(err) => {
                        syscalls.signal_return(task, None);
                        return Outcome::Unwind(err);
                    }
                }
            }
        }
    }
    if let Some(value) = switched {
        return Outcome::Switched(value);
    }
    match (ret, handled) {
        (Ok(value), _) => Outcome::Return(Ok(value)),
        (Err(SysErr::Errno(errno)), _) => Outcome::Return(Err(errno)),
        (Err(SysErr::Restart), None | Some(true)) | (Err(SysErr::RestartNoHand), None) => {
            Outcome::Rerun
        }
        (Err(SysErr::Restart | SysErr::RestartNoHand), Some(_)) => {
            Outcome::Return(Err(Errno::EINTR))
        }
    }
}

async fn instance_abi<S: 'static>(
    env: &AsyncFunctionEnvMut<ExecEnv<S>>,
) -> Option<Arc<dyn AbiInstance<S>>> {
    env.read().await.data().abi.clone()
}

/// Switches the instance back to the vfork parent and lets its ABI resume it.
async fn vfork_resume<S: 'static>(
    env: &AsyncFunctionEnvMut<ExecEnv<S>>,
    parent: TaskId,
    child: TaskId,
) -> VforkResume {
    process::switch(env, parent).await;
    match instance_abi(env).await {
        Some(abi) => abi.vfork_resume(env, child).await,
        None => VforkResume::Unwind(RuntimeError::new("vfork resume before bind")),
    }
}

/// [`complete`] for the generated `wasixv2` shims: the guest's return value (`-errno` on
/// failure), or `None` when the call must run again.
async fn return_to_guest<S: Syscalls + Control + 'static, R: From<i32>>(
    env: &AsyncFunctionEnvMut<ExecEnv<S>>,
    syscalls: &S,
    task: TaskId,
    ret: SysResult<R>,
) -> Option<Result<R, RuntimeError>> {
    match complete(env, syscalls, task, ret).await {
        Outcome::Rerun => None,
        Outcome::Return(Ok(value)) => Some(Ok(value)),
        Outcome::Return(Err(errno)) => Some(Ok(R::from(-errno.0))),
        Outcome::Switched(value) => Some(Ok(R::from(value))),
        Outcome::Unwind(err) => Some(Err(err)),
    }
}
